#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>
#include <iostream>
#include <string>

int main() {
    // The feed handler: a UDP socket on 127.0.0.1, port 0 so the kernel picks a free one
    const int rx = socket(AF_INET, SOCK_DGRAM, 0);
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(0);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    if (bind(rx, reinterpret_cast<sockaddr*>(&addr), sizeof addr) != 0) {
        std::cout << "bind failed\n";
        return 1;
    }
    socklen_t len = sizeof addr;
    getsockname(rx, reinterpret_cast<sockaddr*>(&addr), &len);  // the port it got

    // The exchange: one datagram per update, numbered. Number 3 is lost.
    const int tx = socket(AF_INET, SOCK_DGRAM, 0);
    for (int seq : {1, 2, 4, 5}) {
        const std::string packet = std::to_string(seq) + " AAPL " + std::to_string(19270 + seq);
        sendto(tx, packet.data(), packet.size(), 0, reinterpret_cast<sockaddr*>(&addr), sizeof addr);
    }

    int expected = 1;
    for (int i = 0; i < 4; ++i) {
        char buf[1500];  // one Ethernet packet's worth
        const ssize_t n = recv(rx, buf, sizeof buf, 0);
        const std::string packet(buf, n);
        const int seq = std::stoi(packet);  // reads the number at the front
        if (seq > expected) {
            std::cout << "gap before " << seq << ": missing " << seq - expected << '\n';
        }
        std::cout << "packet " << packet << '\n';
        expected = seq + 1;
    }
    close(tx);
    close(rx);
    return 0;
}

