steps.body:
Exchanges send every packet twice, on an **A feed** and a **B feed** over separate networks, so a packet lost on one is usually there on the other. A feed handler takes whichever copy comes first and drops the second, which is called **arbitration**. It can't sit in `recv` on feed A while the packet it needs waits on feed B.

A socket blocks by default: `recv` puts the thread to sleep in the kernel until data comes. Make it **non-blocking** with `fcntl(fd, F_SETFL, O_NONBLOCK)` from `<fcntl.h>`, and `recv` returns at once. With nothing to read, it returns -1 and sets `errno` to `EAGAIN`, or `EWOULDBLOCK`, which is the same value on Linux and macOS:

```cpp harness
#include <arpa/inet.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>
#include <cerrno>
#include <iostream>

int main() {
    const int fd = socket(AF_INET, SOCK_DGRAM, 0);
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof addr);
    {{code}}
    close(fd);
    return 0;
}
```

```cpp
fcntl(fd, F_SETFL, O_NONBLOCK);  // a new socket has no other flags to keep
char buf[1500];
const ssize_t n = recv(fd, buf, sizeof buf, 0);  // nothing was sent
std::cout << n << ' ' << (errno == EAGAIN ? "would block" : "error") << '\n';  // -1 would block
```

`poll` from `<poll.h>` waits on several descriptors at once. It takes an array of `pollfd`, each a descriptor with `POLLIN` to ask about reading, and a timeout in milliseconds, and returns how many are ready, or 0 when the time runs out. Linux's `epoll` does the same for thousands of sockets, macOS has `kqueue`, and Windows has `WSAPoll` and I/O completion ports. A low-latency handler goes further and never sleeps at all: it spins on its non-blocking sockets on a core of its own, as the advanced lesson *Designing for Low Latency* shows.

The microseconds matter because the first firm to react to a price change gets the trade, and the slower ones trade at a price that's already gone. Light in fiber covers about 200 km a millisecond, so firms rent racks inside the exchange's data center, called **colocation**, and microwave links between Chicago and New Jersey beat fiber by milliseconds. Inside the server, the kernel's network code costs a few microseconds per packet in interrupts, copies, and system calls. **Kernel bypass** skips it: the network card's buffers are mapped into the program, which polls them directly, with AMD Solarflare's OpenOnload and ef_vi, DPDK, or RDMA. The fastest firms run the strategy on the network card itself, in an FPGA.

example.code:
#include <arpa/inet.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <poll.h>
#include <sys/socket.h>
#include <unistd.h>
#include <cerrno>
#include <iostream>
#include <map>
#include <string>
#include <vector>

// A non-blocking UDP socket on 127.0.0.1. Fills in addr with the port it got.
int open_feed(sockaddr_in& addr) {
    const int fd = socket(AF_INET, SOCK_DGRAM, 0);
    addr = sockaddr_in{};
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof addr);
    socklen_t len = sizeof addr;
    getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len);
    fcntl(fd, F_SETFL, O_NONBLOCK);  // recv returns at once, even with nothing to read
    return fd;
}

void publish(int tx, const sockaddr_in& to, const std::vector<int>& seqs) {
    for (int seq : seqs) {
        const std::string packet = std::to_string(seq) + " AAPL " + std::to_string(19270 + seq);
        sendto(tx, packet.data(), packet.size(), 0, reinterpret_cast<const sockaddr*>(&to), sizeof to);
    }
}

int main() {
    sockaddr_in a{}, b{};
    const int feed_a = open_feed(a);
    const int feed_b = open_feed(b);
    const int tx = socket(AF_INET, SOCK_DGRAM, 0);
    publish(tx, a, {1, 2, 3, 5});  // feed A lost 4
    publish(tx, b, {1, 2, 4, 5});  // feed B lost 3

    std::map<int, std::string> updates;  // the first copy of each sequence number
    int packets = 0, duplicates = 0;
    pollfd fds[2] = {{feed_a, POLLIN, 0}, {feed_b, POLLIN, 0}};
    while (packets < 8 && poll(fds, 2, 1000) > 0) {  // sleep until a feed has data, 1 s at most
        for (int fd : {feed_a, feed_b}) {
            char buf[1500];
            ssize_t n;
            while ((n = recv(fd, buf, sizeof buf, 0)) > 0) {  // drain until it would block
                ++packets;
                const std::string packet(buf, n);
                if (!updates.emplace(std::stoi(packet), packet).second) {
                    ++duplicates;  // the other feed was first
                }
            }
        }
    }
    char buf[1500];
    const bool would_block = recv(feed_a, buf, sizeof buf, 0) < 0 && (errno == EAGAIN || errno == EWOULDBLOCK);
