    }
    std::cout << packets << " packets, " << duplicates << " duplicates dropped\n";
    std::cout << "feed A empty, recv would block: " << (would_block ? "yes" : "no") << '\n';
    for (int fd : {feed_a, feed_b, tx}) {
        close(fd);
    }
    return 0;
}

