#include <poll.h>
#include <sys/socket.h>
#include <unistd.h>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

// A non-blocking UDP socket on 127.0.0.1. Fills in addr with the port it got.
int open_feed(sockaddr_in& addr) {
    const int fd = socket(AF_INET, SOCK_DGRAM, 0);
    addr = sockaddr_in{};
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof addr);
    socklen_t len = sizeof addr;
    getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len);
    fcntl(fd, F_SETFL, O_NONBLOCK);
    return fd;
}

// Sends "<seq> AAPL <price>" for each number on one input line, after its feed's letter.
int publish_line(int tx, const sockaddr_in& to) {
    std::string line, letter;
    std::getline(std::cin, line);
    std::istringstream in(line);
    in >> letter;
    int sent = 0;
    for (int seq; in >> seq; ++sent) {
        const std::string packet = std::to_string(seq) + " AAPL " + std::to_string(19270 + seq);
        sendto(tx, packet.data(), packet.size(), 0, reinterpret_cast<const sockaddr*>(&to), sizeof to);
    }
    return sent;
}

int main() {
    sockaddr_in a{}, b{};
    const int feed_a = open_feed(a);
    const int feed_b = open_feed(b);
    const int tx = socket(AF_INET, SOCK_DGRAM, 0);
    const int total = publish_line(tx, a) + publish_line(tx, b);

    std::map<int, std::string> updates;
    int packets = 0, duplicates = 0;
    pollfd fds[2] = {{feed_a, POLLIN, 0}, {feed_b, POLLIN, 0}};
    while (packets < total && poll(fds, 2, 1000) > 0) {
        for (int fd : {feed_a, feed_b}) {
            char buf[1500];
            ssize_t n;
            while ((n = recv(fd, buf, sizeof buf, 0)) > 0) {
                ++packets;
                const std::string packet(buf, n);
                if (!updates.emplace(std::stoi(packet), packet).second) ++duplicates;
            }
        }
    }
    for (const auto& [seq, packet] : updates) std::cout << packet << '\n';
    std::cout << packets << " packets, " << duplicates << " duplicates dropped\n";
    std::cout << "missing from both:";
    const int highest = updates.empty() ? 0 : updates.rbegin()->first;
    int missing = 0;
    for (int seq = 1; seq <= highest; ++seq) {
        if (updates.count(seq) == 0) {
            std::cout << ' ' << seq;
            ++missing;
        }
    }
    std::cout << (missing == 0 ? " none" : "") << '\n';
    for (int fd : {feed_a, feed_b, tx}) close(fd);
    return 0;
}
